package com.quincaisoft.inventory.application;
import com.quincaisoft.inventory.api.*;import com.quincaisoft.inventory.infrastructure.*;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;import java.time.*;
import static com.quincaisoft.inventory.application.InventoryCommands.*;
@Service public class DefaultInventoryCustody implements InventoryCustody {
 private final EntityManager em;private final ScopedTransactions tx;private final InventoryCommands commands;
 public DefaultInventoryCustody(EntityManager em,ScopedTransactions tx){this.em=em;this.tx=tx;commands=new InventoryCommands(em);}
 private Policy view(InventoryRecognitionPolicy p){return new Policy(p.id,p.mode,p.effectiveFrom,p.contractReference,p.status,""+p.version);}
 private Position view(CustomerCustody p){return new Position(p.id,p.saleId,p.customerId,p.warehouseId,p.productId,""+p.quantityMilli,""+p.collectedMilli,""+p.frozenCostXaf,p.status,""+p.version);}
 public List<Policy> policies(){return tx.execute(()->em.createQuery("select p from InventoryRecognitionPolicy p order by p.effectiveFrom desc,p.id",InventoryRecognitionPolicy.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 public Policy requestPolicy(PolicyRequest c){if(c.effectiveFrom()==null||!Set.of("HANDOVER","SALE_WITH_CUSTOMER_CUSTODY").contains(c.mode()))throw new IllegalArgumentException("Recognition mode and effective date required");text(c.contractReference(),240);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"POLICY_REQUEST|"+c,"INVENTORY_RECOGNITION_POLICY",Policy.class,()->{var s=TenantContext.current();var p=new InventoryRecognitionPolicy();p.tenantId=s.tenantId();p.companyId=s.companyId();p.branchId=s.branchId();p.id=UUID.randomUUID();p.mode=c.mode();p.effectiveFrom=c.effectiveFrom();p.contractReference=c.contractReference();p.createdBy=s.actorId();p.createdAt=Instant.now();p.status="DRAFT";em.persist(p);em.flush();return view(p);},Policy::id));}
 public Policy approvePolicy(UUID id,Approve c){long version=quantity(c.version(),true);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"POLICY_APPROVE|"+id+"|"+c,"INVENTORY_RECOGNITION_POLICY",Policy.class,()->{var s=TenantContext.current();var p=em.find(InventoryRecognitionPolicy.class,new InventoryRecognitionPolicy.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(p==null)throw new NoSuchElementException("Policy not found");if(p.version!=version)throw new RevisionConflict("Policy changed");if(!p.status.equals("DRAFT")||p.createdBy.equals(s.actorId()))throw new IllegalStateException("Draft policy and independent finance approver required");p.approvedBy=s.actorId();p.status="APPROVED";em.flush();return view(p);},Policy::id));}
 public List<Position> positions(){return tx.execute(()->em.createQuery("select p from CustomerCustody p order by p.createdAt desc,p.id",CustomerCustody.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 private CustomerCustody position(UUID id){var s=TenantContext.current();var p=em.find(CustomerCustody.class,new CustomerCustody.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(p==null||!p.branchId.equals(s.branchId()))throw new NoSuchElementException("Custody not found");return p;}
 public Position collect(UUID id,Collect c){long q=quantity(c.quantityMilli(),false),version=quantity(c.version(),true);text(c.proofReference(),240);text(c.reason(),2000);return tx.execute(()->commands.once(c.operationId(),"COLLECT|"+id+"|"+c,"CUSTOMER_CUSTODY",Position.class,()->{var p=position(id);if(p.version!=version)throw new RevisionConflict("Custody changed");if(!Set.of("PENDING","PARTIALLY_COLLECTED").contains(p.status)||q>p.quantityMilli-p.collectedMilli)throw new IllegalArgumentException("Collection exceeds remaining customer-owned custody");p.collectedMilli=Math.addExact(p.collectedMilli,q);p.status=p.collectedMilli==p.quantityMilli?"COLLECTED":"PARTIALLY_COLLECTED";var s=TenantContext.current();var fact=new CustodyCollection();fact.tenantId=s.tenantId();fact.companyId=s.companyId();fact.branchId=s.branchId();fact.id=UUID.randomUUID();fact.custodyId=p.id;fact.operationId=c.operationId();fact.quantityMilli=q;fact.proofReference=c.proofReference();fact.actorId=s.actorId();fact.collectedAt=Instant.now();em.persist(fact);em.flush();return view(p);},Position::id));}
 public List<Collection> collections(UUID id){return tx.execute(()->{position(id);return em.createQuery("select c from CustodyCollection c where c.custodyId=:id order by c.collectedAt,c.id",CustodyCollection.class).setParameter("id",id).getResultList().stream().map(c->new Collection(c.id,c.custodyId,""+c.quantityMilli,c.proofReference,c.actorId,c.collectedAt)).toList();});}
}
